// API reference pages for each repo with `api`, generated by TypeDoc from the
// declaration files its package.json exports, at <section>/api/. The repo's
// typedoc.json, if it has one, is used too.
import { existsSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { createStarlightTypeDocPlugin } from "starlight-typedoc";
import { sections, repoDir } from "./sources.js";

const importPaths = fileURLToPath(new URL("./plugins/typedoc-import-paths.js", import.meta.url));

export const apis = sections.filter((source) => source.api).map((source) => {
  const dir = repoDir(source);
  const pkg = JSON.parse(readFileSync(`${dir}/package.json`, "utf8"));
  const [plugin, sidebarGroup] = createStarlightTypeDocPlugin();
  return {
    section: source.section,
    sidebarGroup,
    plugin: plugin({
      entryPoints: Object.values(pkg.exports).map((target) => `${dir}/${target.types}`),
      tsconfig: `${dir}/tsconfig.json`,
      output: `${source.section}/api`,
      sidebar: { label: "API", collapsed: true },
      typeDoc: {
        ...existsSync(`${dir}/typedoc.json`) && { options: `${dir}/typedoc.json` },
        excludeExternals: true,
        plugin: [importPaths],
        router: "import-paths",
        entryFileName: "index",
        // The package's main module is the API's front page.
        entryModule: pkg.name
      }
    })
  };
});
